import{c as r,Q as a,j as s,m as i}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"FlowSteer: Towards Agents Designing Agentic Workflows via Reinforced Progressive Canvas Editing","description":"","frontmatter":{"url":"https://arxiv.org/abs/2602.01664","title":"FlowSteer: Towards Agents Designing Agentic Workflows via Reinforced Progressive Canvas Editing","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2602.01664,"authors":["Mingda Zhang","Wenjin Liu","Tiesunlong Shen","Qika Lin","Rui Mao","Erik Cambria","Xiaoying Tang","Haoran Luo"],"pdf_path":"pdfs/2602.01664.pdf","published_date":"2026-02-02T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-02-02-flowsteer-agents-designing-agentic-workflows-2602-01664.md","filePath":"research/papers/2026-02-02-flowsteer-agents-designing-agentic-workflows-2602-01664.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-02-02-flowsteer-agents-designing-agentic-workflows-2602-01664.md"};function t(o,e,g,l,d,c){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="flowsteer-towards-agents-designing-agentic-workflows-via-reinforced-progressive-canvas-editing" tabindex="-1">FlowSteer: Towards Agents Designing Agentic Workflows via Reinforced Progressive Canvas Editing <a class="header-anchor" href="#flowsteer-towards-agents-designing-agentic-workflows-via-reinforced-progressive-canvas-editing" aria-label="Permalink to &quot;FlowSteer: Towards Agents Designing Agentic Workflows via Reinforced Progressive Canvas Editing&quot;">​</a></h1><p><strong>Authors</strong>: Mingda Zhang, Wenjin Liu, Tiesunlong Shen, Qika Lin, Rui Mao, Erik Cambria, Xiaoying Tang, Haoran Luo <strong>Published</strong>: February 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2602.01664" target="_blank" rel="noreferrer">https://arxiv.org/abs/2602.01664</a><strong>arXiv ID</strong>: 2602.01664 <strong>Categories</strong>: Artificial Intelligence (cs.AI); Machine Learning (cs.LG) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2602.01664" target="_blank" rel="noreferrer">research/papers/pdfs/2602.01664.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>This research addresses workflow construction challenges by introducing a new paradigm where a single agent itself end-to-end designs the workflow that a downstream executor runs. The authors present the Workflow Canvas, an executable graph-state environment providing syntax-checked feedback for atomic edits. They propose Reinforced Progressive Canvas Editing, training a policy agent via reinforcement learning to issue one atomic edit per turn based on real feedback. The framework supports diverse operator libraries and interchangeable language model backends. Testing across twelve datasets demonstrates FlowSteer significantly outperforms baselines across various tasks, with code made publicly available.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>提出新範式：讓單一 agent 端到端自行設計下游執行器要跑的 workflow，而非人工預先設計固定 pipeline。</li><li>核心機制 Workflow Canvas：可執行的 graph-state 環境，對每次 atomic edit 提供語法檢查回饋；用 Reinforced Progressive Canvas Editing 訓練 policy agent，每輪基於真實回饋發出一次原子編輯（而非一次生成整個 workflow）。</li><li>支援多樣化 operator library 與可替換 LLM backend；12 個資料集上顯著優於基準，並開源程式碼。</li><li><strong>Workspace 關聯</strong>：與本庫既有 Loop/Workflow Engineering 收錄的 sew-2505-18646（自我演化多代理 workflow）主題相近，但方法不同——本文用「漸進式原子編輯 + RL policy」而非整體生成/演化，可作為未來設計「動態 workflow 生成 agent」時的替代方案參照。</li></ul>',8)])])}const p=r(n,[["render",t]]);export{h as __pageData,p as default};
